sn_aia_tool.script:
(function(inputs) {

    var rec = new GlideRecord('x_birl3_clm_customer_performance');
    rec.initialize();

    rec.company_name = inputs.company_name;
    rec.final_recommendation = inputs.final_recommendation;
    rec.current_stock_price = inputs.current_stock_price;
    rec.key_news_highlights = inputs.key_news_highlights;
    rec.market_stock_insight = inputs.market_stock_insight;

    var sysId = rec.insert();

    return {
        output: "Record created successfully",
        company_name: inputs.company_name,
        recommendation: inputs.final_recommendation,
        record_sys_id: sysId
    };

})(inputs);
